INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_4_25',
  'A development team needs to monitor the CPU utilization of their Amazon EC2 instances and receive notifications when it exceeds 80% for more than 5 minutes. Which CloudWatch feature should they configure?',
  'mcq',
  '["CloudWatch Logs","CloudWatch Events","CloudWatch Dashboards","CloudWatch Alarms"]'::json,
  '{3}',
  'Option D (CloudWatch Alarms) is the correct feature for this scenario. CloudWatch Alarms allow you to watch a single metric (like CPU utilization) and trigger actions (like sending notifications via Amazon SNS) when the metric breaches a specified threshold for a defined period. Option A (CloudWatch Logs) is for collecting and storing log data. Option B (CloudWatch Events), now Amazon EventBridge, delivers a near real-time stream of system events that describe changes in AWS resources. Option C (CloudWatch Dashboards) are for visualizing metrics and logs, not for triggering actions based on thresholds.',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  5,
  NULL,
  NULL,
  'm_50_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
