INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_3_32',
  'Which Amazon Route 53 routing policy directs traffic to resources based on the user''s geographic location?',
  'mcq',
  '["Simple routing policy.","Failover routing policy.","Geolocation routing policy.","Weighted routing policy."]'::json,
  '{2}',
  'Option C (correct) is the Geolocation routing policy, which allows you to route traffic to your resources based on the geographic location of your users. Option A is for single resources. Option B is for active-passive failover. Option D is for distributing traffic proportionally to multiple resources.',
  NOW(),
  'quiz_domain51_11',
  NOW(),
