INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_4_25',
  'Which AWS services allow you to capture detailed information about network traffic within your VPC for security analysis and troubleshooting? (Select TWO.)',
  'multiple',
