INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_5_24',
  'A company is designing a hybrid cloud architecture and needs to establish a private, dedicated network connection between their on-premises data center and their AWS VPCs. They also require a backup connectivity solution. Which AWS services should they consider? (Select TWO.)',
  'multiple',
  '["AWS Direct Connect","AWS Site-to-Site VPN","Amazon Connect","AWS Client VPN","Amazon S3 Transfer Acceleration"]'::json,
  '{0,1}',
  'Option A (AWS Direct Connect) provides a dedicated network connection from your premises to AWS, offering consistent network performance and reduced bandwidth costs. Option B (AWS Site-to-Site VPN) creates a secure, encrypted tunnel over the public internet between your data center and your VPC, serving as an excellent backup solution for Direct Connect or a primary connection for less critical workloads. Option C (Amazon Connect) is a cloud contact center service. Option D (AWS Client VPN) provides VPN access for individual users, not site-to-site connectivity. Option E (Amazon S3 Transfer Acceleration) optimizes S3 data transfers, not general network connectivity.',
  NOW(),
  'quiz_domain50_11',
