INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_1_48',
  'Which AWS service allows you to establish a dedicated private network connection from your on-premises data center to AWS?',
  'mcq',
  '["AWS Direct Connect","Amazon VPC Peering","AWS Site-to-Site VPN","AWS Transit Gateway"]'::json,
  '{0}',
  'Option A (correct), AWS Direct Connect, provides a dedicated private connection from your on-premises data center to AWS, reducing network costs, increasing bandwidth throughput, and providing a more consistent network experience than internet-based connections. Option B, Amazon VPC Peering, connects two VPCs. Option C, AWS Site-to-Site VPN, uses the public internet for connectivity. Option D, AWS Transit Gateway, is a network transit hub.',
  NOW(),
