INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_4_36',
  'Order the steps to create a basic Amazon CloudWatch alarm that monitors an Amazon EC2 instance''s CPU utilization.',
  'ordering',
  '["Define the threshold and period for the metric.","Select the Amazon EC2 CPU Utilization metric.","Choose an action to perform when the alarm state changes (e.g., send an Amazon SNS notification).","Specify the EC2 instance to monitor."]'::json,
  '{1,3,0,2}',
  'To create a CloudWatch alarm, you first need to select the specific metric you want to monitor, in this case, the Amazon EC2 CPU Utilization metric (Option B). Then, you specify the particular EC2 instance for which this metric should be monitored (Option D). After selecting the metric and resource, you define the threshold and evaluation period that trigger the alarm (Option A). Finally, you choose an action, such as sending an Amazon SNS notification, to be performed when the alarm state is met (Option C).',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  1,
  NULL,
  NULL,
  'm_50_4',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
