INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_6_35',
  'Arrange the following steps to establish a VPC peering connection between two Amazon VPCs.',
  'ordering',
  '["Accept the peering connection request from the requester VPC.","Create a VPC peering connection request from the requester VPC to the acceptor VPC.","Update route tables in both VPCs to allow traffic between them.","Ensure the CIDR blocks of the two VPCs do not overlap."]'::json,
  '{3,1,0,2}',
  'Before establishing a VPC peering connection, it''s crucial to ensure that the CIDR blocks of the two VPCs do not overlap (Option D). Next, the owner of the requester VPC initiates a VPC peering connection request to the acceptor VPC (Option B). The owner of the acceptor VPC then accepts this peering connection request (Option A). Finally, route tables in both VPCs must be updated to include routes that direct traffic to the peered VPC through the peering connection (Option C).',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  28,
  NULL,
  NULL,
  'm_50_6',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_6_36',
  'Arrange the steps to share a subnet with another AWS account using AWS Resource Access Manager (RAM).',
  'ordering',
  '["Associate the resource share with the desired AWS account.","Create a new resource share in AWS RAM.","Add the subnet as a resource to the resource share.","Accept the resource share invitation in the recipient AWS account."]'::json,
  '{1,2,0,3}',
  'To share a subnet using AWS RAM, you first create a new resource share in the AWS Resource Access Manager console (Option B). Next, you add the specific subnet you wish to share as a resource to this newly created resource share (Option C). Then, you associate the resource share with the target AWS account that will receive access (Option A). Finally, the recipient AWS account must accept the resource share invitation to gain access to the shared subnet (Option D).',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  29,
