INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_4_50',
  'Match each AWS service or feature to its primary logging or monitoring purpose.',
  'matching',
  '{"A":"AWS CloudWatch","B":"VPC Flow Logs","C":"CloudWatch Logs"}'::json,
  NULL,
  'AWS CloudWatch (left[0]) is a monitoring and observability service that provides data and actionable insights to monitor applications, respond to system-wide performance changes, and optimize resource utilization. VPC Flow Logs (left[1]) capture information about the IP traffic going to and from network interfaces in a VPC, which is crucial for network troubleshooting and security analysis. CloudWatch Logs (left[2]) allows you to centralize logs from all of your systems, applications, and AWS services, and then monitor, store, and access your log files.',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  1,
  '{"left":["AWS CloudWatch","VPC Flow Logs","CloudWatch Logs"],"right":["Collects metrics and logs","Records IP traffic flow","Stores and monitors log data"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_50_4',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
