  NOW(),
  8,
  '{"left":["Amazon S3 Access Logs","Elastic Load Balancing Access Logs","Amazon CloudFront Access Logs"],"right":["Record requests made to S3 buckets","Capture detailed information about requests sent to load balancers","Log all viewer requests for content delivered by CloudFront"]}'::json,
