  'quiz_domain50_11',
  NOW(),
  11,
  '{"left":["Reachability Analyzer","Transit Gateway Network Manager","CloudWatch Logs Insights","CloudWatch Alarms"],"right":["Analyzes network reachability between resources","Monitors global network performance and events","Interactively queries and analyzes log data","Notifies when a metric crosses a threshold"]}'::json,
  '{"left":[0,1,2,3],"right":[0,1,2,3]}'::jsonb,
  'm_50_4',
  'hard'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
