  NOW(),
  'quiz_domain50_11',
  NOW(),
  17,
  '{"left":["Direct Connect Location","Direct Connect Connection","Direct Connect Gateway"],"right":["Physical network facility","Dedicated network circuit","Global resource for DX connections"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_50_5',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_5_48',
  'Match each Direct Connect Virtual Interface (VIF) type to its access purpose.',
  'matching',
  '{"A":"Public VIF","B":"Private VIF","C":"Transit VIF"}'::json,
  NULL,
