INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_50_m_50_5_50',
  'Match the BGP attribute to its effect on network routing.',
  'matching',
  '{"A":"AS_PATH","B":"LOCAL_PREF","C":"MED"}'::json,
  NULL,
  'The AS_PATH attribute (left[0]) is a list of Autonomous Systems (AS) numbers that a route has traversed. A shorter AS_PATH is generally preferred, meaning a longer path is less preferred. LOCAL_PREF (left[1]) is used to influence outbound traffic from an Autonomous System (AS) by indicating the preferred exit point. Multi-Exit Discriminator (MED) (left[2]) is used to influence inbound traffic to an AS, helping external ASes choose the best entry point.',
  NOW(),
  'quiz_domain50_11',
  NOW(),
  20,
  '{"left":["AS_PATH","LOCAL_PREF","MED"],"right":["Longer path is less preferred","Influence outbound traffic from an AS","Influence inbound traffic to an AS"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_50_5',
  'medium'
);

