INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_4_59',
  'A global organization is expanding its AWS footprint, requiring the creation of numerous VPCs, subnets, and routing configurations across various accounts and Regions. The network team wants to standardize the network architecture and ensure that all new deployments adhere to corporate policies. They are looking for a solution that allows them to define network components programmatically using Python, TypeScript, or Java. Match the AWS CDK construct to its purpose in defining network resources.',
  'matching',
  '{"A":"CfnResource","B":"Construct Library","C":"Aspects"}'::json,
  NULL,
  'CfnResource (left[0]) represents a low-level CloudFormation resource (right[0]) within the AWS CDK, allowing direct access to CloudFormation properties. The Construct Library (left[1]) provides higher-level, opinionated components (right[1]) that encapsulate best practices and simplify the definition of common AWS architectures, such as VPCs and databases. Aspects (left[2]) in CDK allow you to apply modifications across resources (right[2]) in a construct tree, enabling cross-cutting concerns like security tagging or compliance checks to be enforced uniformly.',
  NOW(),
  'quiz_domain51_11',
  NOW(),
  17,
  '{"left":["CfnResource","Construct Library","Aspects"],"right":["Low-level CloudFormation resource","Higher-level, opinionated components","Apply modifications across resources"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_51_4',
  'hard'
);

