INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_3_50',
  'A company has multiple AWS accounts and needs to share a private hosted zone across several VPCs in different accounts for internal application discovery. Match the sharing mechanism to its capability.',
  'matching',
  '{"A":"AWS Resource Access Manager (RAM)","B":"VPC Peering","C":"Route 53 Resolver"}'::json,
  NULL,
  'AWS Resource Access Manager (RAM) (left item 0) is used to share AWS resources, including Route 53 Private Hosted Zones, across multiple AWS accounts or within your AWS Organization. VPC Peering (left item 1) connects two VPCs directly, enabling network traffic between them but does not inherently share DNS zones. Route 53 Resolver (left item 2) is used for forwarding DNS queries between VPCs and on-premises networks, not for sharing hosted zones directly.',
  NOW(),
  'quiz_domain51_11',
  NOW(),
  26,
  '{"left":["AWS Resource Access Manager (RAM)","VPC Peering","Route 53 Resolver"],"right":["Share resources across accounts","Connect two VPCs directly","Forward DNS queries"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_51_3',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
