INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_3_52',
  'An organization with an on-premises data center needs to resolve DNS queries for AWS resources from on-premises servers, and vice-versa, without manually updating host files. Match the Route 53 Resolver component to its function.',
  'matching',
