INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_1_46',
  'Match the hybrid connectivity service to its characteristic.',
  'matching',
  '{"A":"AWS Direct Connect","B":"AWS Site-to-Site VPN","C":"AWS Client VPN"}'::json,
  NULL,
  'AWS Direct Connect (left item 0) provides a dedicated private network connection from your on-premises data center to AWS. AWS Site-to-Site VPN (left item 1) creates an encrypted connection over the public internet between your on-premises network and your AWS VPC. AWS Client VPN (left item 2) enables secure remote access for individual users to AWS resources and on-premises networks.',
  NOW(),
  'quiz_domain51_11',
  NOW(),
  53,
  '{"left":["AWS Direct Connect","AWS Site-to-Site VPN","AWS Client VPN"],"right":["Dedicated private network connection","Encrypted connection over public internet","Secure remote access for users"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_51_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_1_47',
  'Match the routing protocol or method to its typical use case in hybrid networks.',
  'matching',
  '{"A":"Border Gateway Protocol (BGP)","B":"Static Routing","C":"Dynamic Routing"}'::json,
  NULL,
  'Border Gateway Protocol (BGP) (left item 0) is a standard routing protocol used to exchange routing and reachability information between autonomous systems (like your on-premises network and AWS). Static Routing (left item 1) involves manually configured fixed routes that do not change unless manually updated. Dynamic Routing (left item 2), often implemented with BGP in AWS, automatically adjusts routes based on real-time network conditions and changes.',
  NOW(),
  'quiz_domain51_11',
  NOW(),
  54,
  '{"left":["Border Gateway Protocol (BGP)","Static Routing","Dynamic Routing"],"right":["Exchanging routing information between autonomous systems","Manually configured fixed routes","Automatically adjusting routes based on network conditions"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_51_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_1_48',
  'Match the AWS Direct Connect component to its role.',
  'matching',
  '{"A":"Direct Connect Connection","B":"Virtual Interface","C":"Direct Connect Gateway"}'::json,
  NULL,
  'A Direct Connect Connection (left item 0) is the physical network link established between your network and an AWS Direct Connect location. A Virtual Interface (VIF) (left item 1) is a logical connection configured over your Direct Connect connection, allowing access to AWS services. A Direct Connect Gateway (left item 2) is a global resource that allows you to connect your AWS Direct Connect connection to one or more VPCs in any AWS Region.',
  NOW(),
