  NOW(),
  55,
  '{"left":["Direct Connect Connection","Virtual Interface","Direct Connect Gateway"],"right":["Physical network link to AWS","Logical connection over a DX connection","Connects DX connections to multiple VPCs"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_51_1',
  'easy'
);

