INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_51_m_51_1_53',
  'Match each VPN component to its role in an AWS Site-to-Site VPN connection.',
  'matching',
  '{"A":"Virtual Private Gateway","B":"Customer Gateway","C":"VPN Connection"}'::json,
  NULL,
  'A Virtual Private Gateway (left item 0) is the VPN concentrator on the Amazon side of a Site-to-Site VPN connection. A Customer Gateway (left item 1) is a resource that you create in AWS to represent your on-premises VPN device or software application. A VPN Connection (left item 2) is the encrypted tunnel established between the Virtual Private Gateway and the Customer Gateway.',
  NOW(),
  'quiz_domain51_11',
