INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_1_44',
  'Which AWS service allows you to deploy a highly available, managed firewall for your Amazon VPCs to filter traffic at the VPC boundary?',
