INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_1_45',
  'When designing a multi-tier application in an Amazon VPC, which AWS service or feature is typically used to isolate the database tier from direct internet access?',
