INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_2_46',
  'A company needs to collect and process real-time streaming data from thousands of IoT devices for immediate analytics. Which AWS service is best suited for this purpose?',
  'mcq',
  '["Amazon SQS","Amazon Kinesis","Amazon S3","Amazon RDS"]'::json,
