INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_1_101',
  'Match the AWS service to its use case for private network access.',
  'matching',
  '{"A":"AWS PrivateLink","B":"VPC Peering","C":"VPC Endpoint"}'::json,
  NULL,
