INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_1_112',
  'A global company is implementing a hybrid cloud architecture, requiring secure and scalable network connectivity between its on-premises data centers and AWS. They need to manage routing for thousands of IP prefixes and ensure high throughput for critical applications, while also considering cost and operational overhead.',
