  'm_52_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_2_98',
  'Match the AWS networking tool to its use case for troubleshooting.',
  'matching',
  '{"A":"AWS Reachability Analyzer","B":"Amazon VPC Traffic Mirroring","C":"AWS Network Manager"}'::json,
  NULL,
  'AWS Reachability Analyzer is a network diagnostics tool that troubleshoots reachability between two endpoints in your VPCs. Amazon VPC Traffic Mirroring allows you to copy network traffic from an Elastic Network Interface (ENI) of an Amazon EC2 instance and send it to an out-of-band security or monitoring appliance for deep packet inspection. AWS Network Manager provides a central dashboard to manage and monitor your global network across AWS and on-premises environments.',
