  '{"left":["Packet Loss","Misconfigured Security Group","Incorrect Route Table Entry"],"right":["Check network latency/jitter","Review ingress/egress rules","Verify destination CIDR blocks"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_52_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
