INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_2_102',
  'Match the network issue to its common cause.',
  'matching',
  '{"A":"MTU Issues","B":"Routing Blackhole","C":"Security Group Block"}'::json,
  NULL,
  'MTU (Maximum Transmission Unit) Issues often lead to packet fragmentation or dropped packets when the packet size exceeds the MTU of a network path. A Routing Blackhole occurs when traffic is routed to a destination with no valid next hop, causing packets to be dropped silently. A Security Group Block happens when a firewall rule in a security group explicitly denies or implicitly blocks traffic based on port, protocol, or IP address.',
  NOW(),
  'quiz_domain52_11',
  NOW(),
  25,
  '{"left":["MTU Issues","Routing Blackhole","Security Group Block"],"right":["Packet fragmentation","No route to destination","Firewall rule denial"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_52_2',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_2_103',
  'Match the AWS networking service to its primary monitoring capability.',
