INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_52_m_52_2_108',
  'Match AWS services used for collecting and processing network log data.',
  'matching',
  '{"A":"Amazon CloudWatch Logs","B":"Amazon S3","C":"Amazon Kinesis Data Firehose"}'::json,
  NULL,
  'Amazon CloudWatch Logs (left item 0) is a service for centralizing and monitoring log data from AWS services and applications. Amazon S3 (left item 1) is a common destination for storing raw VPC Flow Logs due to its durability and scalability. Amazon Kinesis Data Firehose (left item 2) can be used to deliver streaming data, including VPC Flow Logs, to various destinations like Amazon S3, Amazon Redshift, or Splunk.',
