INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_3_91',
  'A developer needs to secure a web application by deploying an SSL/TLS certificate to an Application Load Balancer. Arrange the following steps in the correct order to provision and deploy a public certificate using AWS Certificate Manager (ACM).',
  'ordering',
