INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_3_98',
  'A development team needs to ensure that all data transfers to and from an Amazon S3 bucket are encrypted in transit using TLS. Order the steps to configure the S3 bucket policy to enforce this requirement.',
  'ordering',
  '["Add a condition to the bucket policy to check for ''aws:SecureTransport'': ''false''.","Create a new S3 bucket policy or modify an existing one.","Set the ''Effect'' to ''Deny'' for the policy statement.","Specify ''s3:*'' as the action and ''*'' as the principal."]'::json,
  '{1,3,0,2}',
  'To enforce TLS for an S3 bucket, you first need to create or modify an S3 bucket policy (Option B). Within this policy, you specify ''s3:*'' as the action and ''*'' as the principal to cover all S3 actions and all users (Option D). The core of enforcing TLS is to add a condition that checks if ''aws:SecureTransport'' is ''false'' (Option A), meaning the request is not using HTTPS. Finally, for any request that meets this condition (i.e., not using HTTPS), the ''Effect'' must be set to ''Deny'' (Option C) to block the insecure access.',
  NOW(),
  'quiz_domain53_11',
  NOW(),
  8,
  NULL,
  NULL,
  'm_53_3',
  'medium'
);

