INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_1_94',
  'A developer needs to configure a security group for an Amazon EC2 instance to allow inbound SSH access from a specific IP address range. Order the steps to achieve this.',
