  'm_53_3',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_3_114',
  'Match each technology or feature to its role in protecting data in transit or at rest.',
  'matching',
  '{"A":"TLS","B":"IPsec","C":"Amazon S3 Server-Side Encryption"}'::json,
  NULL,
  'TLS (Transport Layer Security) is a cryptographic protocol designed to provide communications security over a computer network, commonly used to encrypt HTTP traffic (HTTPS). IPsec (Internet Protocol Security) is a suite of protocols for securing Internet Protocol (IP) communications by authenticating and encrypting each IP packet of a communication session. Amazon S3 Server-Side Encryption protects data at rest by encrypting objects before saving them to disk and decrypting them when they are downloaded.',
  NOW(),
  'quiz_domain53_11',
  NOW(),
  3,
  '{"left":["TLS","IPsec","Amazon S3 Server-Side Encryption"],"right":["Encrypts HTTP/HTTPS traffic","Encrypts network layer communications","Encrypts objects stored in Amazon S3"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_53_3',
  'easy'
);

