INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_53_m_53_3_117',
  'Match each AWS service to its primary function in managing SSL/TLS certificates for network communication.',
  'matching',
  '{"A":"AWS Certificate Manager (ACM)","B":"AWS Private Certificate Authority (PCA)","C":"Amazon CloudFront"}'::json,
  NULL,
  'AWS Certificate Manager (ACM) (left[0]) is primarily used for provisioning, managing, and deploying public and private SSL/TLS certificates for use with integrated AWS services like Elastic Load Balancing and Amazon CloudFront (right[0]). AWS Private Certificate Authority (PCA) (left[1]) allows you to create and manage your own private CAs for issuing private certificates within your organization, providing a managed private CA service (right[1]). Amazon CloudFront (left[2]) is a content delivery network that can use custom SSL certificates managed by ACM to secure content delivery (right[2]).',
  NOW(),
  'quiz_domain53_11',
